<?php require 'config.php';admin();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$act=$_POST['action']??'';$id=(int)($_POST['id']??0);if($act==='save'){$t=trim($_POST['title']??'');$d=trim($_POST['description']??'');$v=trim($_POST['venue']??'');$date=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$_POST['event_date']??'');$cap=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT);if(strlen($t)<3||strlen($t)>150||strlen($d)<5||strlen($v)<2||strlen($v)>150||!$date||$date->format('Y-m-d\TH:i')!==($_POST['event_date']??'')||$cap===false||$cap<1)$err='Invalid event details.';else{if($id){$s=$db->prepare('SELECT COUNT(*) FROM registrations WHERE event_id=?');$s->execute([$id]);if($cap<$s->fetchColumn())$err='Capacity below registrations.';else{$s=$db->prepare('UPDATE events SET title=?,description=?,venue=?,event_date=?,capacity=? WHERE id=?');$s->execute([$t,$d,$v,$date->format('Y-m-d H:i:s'),$cap,$id]);}}else{$s=$db->prepare('INSERT INTO events(title,description,venue,event_date,capacity) VALUES(?,?,?,?,?)');$s->execute([$t,$d,$v,$date->format('Y-m-d H:i:s'),$cap]);}if(!$err)go('admin.php');}}elseif($act==='toggle'&&$id){$s=$db->prepare('UPDATE events SET active=1-active WHERE id=?');$s->execute([$id]);go('admin.php');}}head('Admin');?><h1>Admin dashboard</h1><div class="grid"><?php foreach(['Attendees'=>"SELECT COUNT(*) FROM users WHERE role='attendee'",'Events'=>'SELECT COUNT(*) FROM events','Registrations'=>'SELECT COUNT(*) FROM registrations'] as $label=>$sql):?><article class="card"><h2><?=h($db->query($sql)->fetchColumn())?></h2><?=h($label)?></article><?php endforeach;?></div><h2>Create event</h2><section class="card"><p><?=h($err)?></p><form method="post"><input type="hidden" name="token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><label>Title<input name="title" required maxlength="150"></label><label>Description<textarea name="description" required></textarea></label><label>Venue<input name="venue" required maxlength="150"></label><label>Date<input type="datetime-local" name="event_date" required></label><label>Capacity<input type="number" name="capacity" min="1" required></label><button>Create event</button></form></section><h2>Manage events</h2><div class="grid"><?php foreach($db->query('SELECT * FROM events ORDER BY id DESC') as $e):?><article class="card"><form method="post"><input type="hidden" name="token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($e['id'])?>"><label>Title<input name="title" value="<?=h($e['title'])?>" required></label><label>Description<textarea name="description" required><?=h($e['description'])?></textarea></label><label>Venue<input name="venue" value="<?=h($e['venue'])?>" required></label><label>Date<input type="datetime-local" name="event_date" value="<?=h(date('Y-m-d\TH:i',strtotime($e['event_date'])))?>" required></label><label>Capacity<input type="number" name="capacity" min="1" value="<?=h($e['capacity'])?>" required></label><button>Save</button></form><form method="post"><input type="hidden" name="token" value="<?=h(token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=h($e['id'])?>"><button><?= $e['active']?'Hide':'Show'?></button></form></article><?php endforeach;?></div><h2>Registrations</h2><div class="table"><table><tr><th>Attendee</th><th>Email</th><th>Event</th></tr><?php foreach($db->query('SELECT u.name,u.email,e.title FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id ORDER BY r.id DESC') as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['email'])?></td><td><?=h($x['title'])?></td></tr><?php endforeach;?></table></div><?php foot();?>